const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const ukGeometry = ee.Geometry.Rectangle([-10.0, 49.0, 2.0, 61.0]); // UK bounding box
  const targetDate = '2022-07-19';

  // 2. Data Acquisition - ECMWF ERA5 for temperature
  const tempCollection = ee.ImageCollection('ECMWF/ERA5/DAILY')
    .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'))
    .filterBounds(ukGeometry)
    .select('mean_2m_air_temperature');

  const collectionSize = tempCollection.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get temperature image and convert to Fahrenheit
  const tempImage = tempCollection.first();

  // Convert from Kelvin to Fahrenheit: F = (K - 273.15) * 9/5 + 32
  const tempF = tempImage.expression(
    '(tempK - 273.15) * 9/5 + 32',
    {tempK: tempImage.select('mean_2m_air_temperature')}
  ).rename('temperature_fahrenheit');

  // 4. Count pixels above 100°F
  const above100 = tempF.gt(100);
  const pixelStats = above100.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: ukGeometry,
    scale: 10000,
    maxPixels: 1e9
  });

  const countAbove100 = pixelStats.get('temperature_fahrenheit').getInfo();
  console.log(`Pixels above 100°F: ${countAbove100}`);

  // Get max temperature for validation
  const maxTemp = tempF.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: ukGeometry,
    scale: 10000,
    maxPixels: 1e9
  }).get('temperature_fahrenheit').getInfo();

  console.log(`Max temperature: ${maxTemp?.toFixed(1)}°F`);

  // 5. Validation & Final Answer
  if (countAbove100 === null || maxTemp === null) {
    console.log("<answer>C3</answer>");
  } else if (countAbove100 === 0) {
    console.log("<answer>B</answer>");
  } else if (maxTemp > 150 || maxTemp < -50) { // Sanity check for temperature range
    console.log("<answer>C3</answer>");
  } else {
    console.log("<answer>A</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
